    public static int errorCodeFromString(String str) {
        int i = UNKNOWN_PLAYREADY_ERROR.mErrorCode;
        if (str == null) {
            return i;
        }
        String[] strArrSplit = str.toLowerCase(Locale.US).split("[^0-9a-fx]+", 0);
        if (strArrSplit.length > 0) {
            str = strArrSplit[0];
        }
        if (str.matches("^[0-9a-f]+$")) {
            str = "0x" + str;
        }
        if (!str.matches("^0x[0-9a-f]+$")) {
            return i;
        }
        try {
            long jLongValue = Long.decode(str).longValue();
            return (jLongValue >>> 32) == 0 ? (int) jLongValue : i;
        } catch (NumberFormatException unused) {
            DLog.devf("Could not parse \"%s\" as a hex number", str);
            return i;
        }
    }

